import json, secrets, redis
r = redis.Redis(host="sessions", decode_responses=True)
TTL = 1800

def new_session(user_id: int) -> str:
    sid = secrets.token_urlsafe(32)          # goes back as an HttpOnly, Secure cookie
    r.setex(f"sess:{sid}", TTL, json.dumps({"uid": user_id}))
    return sid

def load_session(sid: str):
    raw = r.get(f"sess:{sid}")      # None => expired or revoked, re-authenticate
    if raw is not None:
        r.expire(f"sess:{sid}", TTL)      # sliding expiry
    return raw and json.loads(raw)

upstream api {
    least_conn;                     # better default than round robin for HTTP
    server 10.0.1.11:8080 max_fails=3 fail_timeout=30s;
    server 10.0.1.12:8080 max_fails=3 fail_timeout=30s;
    keepalive 64;                   # reuse upstream connections
}

# affinity variant: same URI -> same backend, minimal reshuffle if the pool changes
upstream cache_tier {
    hash $request_uri consistent;
    server 10.0.2.11:6081;
    server 10.0.2.12:6081;
}

# consistent hashing with virtual nodes: adding a shard moves ~1/N of keys, not all
import bisect, hashlib

class ShardRing:
    def __init__(self, shards, vnodes=128):
        self.ring = []
        for s in shards:
            for i in range(vnodes):
                h = int(hashlib.blake2b(f"{s}#{i}".encode(), digest_size=8).hexdigest(), 16)
                self.ring.append((h, s))
        self.ring.sort()
        self.points = [h for h, _ in self.ring]
    def route(self, key: str) -> str:
        h = int(hashlib.blake2b(key.encode(), digest_size=8).hexdigest(), 16)
        return self.ring[bisect.bisect(self.points, h) % len(self.ring)][1]

CREATE TABLE idempotency_keys (
  key           text PRIMARY KEY,     -- uniqueness enforced here, not in code
  account_id    bigint      NOT NULL,
  request_hash  text        NOT NULL, -- same key + different body => reject
  response_code int,
  response_body jsonb,
  created_at    timestamptz NOT NULL DEFAULT now()
);

-- one transaction covers both the record and the effect:
