# rate is the sustained refill, burst is the bucket depth; 10m of shared state
limit_req_zone $binary_remote_addr zone=perip:10m  rate=10r/s;
limit_req_zone $http_x_api_key     zone=perkey:10m rate=100r/s;

server {
    location /api/ {
        limit_req zone=perkey burst=200 nodelay;   # allow a burst, then enforce
        limit_req_status 429;                      # not 503, and never a silent drop
        limit_req_log_level warn;
        proxy_pass http://api;
    }
}
